def run_sql_mgmt(sql):
    d = json.dumps({
        'action': 'supabase_execute_sql_management',
        'confirm': True,
        'confirmText': 'CONFIRM_IVX_SUPABASE_MIGRATION',
        'input': {'sql': sql}
    }).encode()
    req = urllib.request.Request(f'{BASE}/api/ivx/developer-deploy/action', data=d, headers=h, method='POST')
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            result = json.loads(r.read())
            return result.get('result', {})
    except Exception as e:
        return {'error': str(e)}

# Fix jv_partners RLS
