for t in ['jv_partners', 'brokers', 'agents', 'land_owners', 'tokenized_investors', 'investors', 'buyers']:
    resp = run_sql_mgmt(f"SELECT count(*) AS cnt FROM {t};")
    rows = resp.get('rows', [])
    if rows:
        print(f"  {t}: {rows[0].get('cnt', '?')}")
PYEOF

